/*
 * The slave firmware as it runs on an ATtiny85: the AVR build of the slave library and its classic HAL (test/avr/
 * firmware/fw_slave.c) on devices simulated by simavr, against the real master on the bus simulation, next to host
 * slave cores. Covers what the host tests cannot: the code generated by avr-gcc, the pin change interrupt, the HAL
 * registers, SLAVE_INFO from flash, the atomic sections, and a blind section with interrupts really disabled. Also
 * measures the ISR, the response time to a pin change, and the stack depth.
 */
#include <stdio.h>
#include <string.h>

#include "avr_slave.h"
#include "fixture.h"

#define MCU "attiny85"
#define F_CPU_HZ 8000000u
#define FW(name) HUBUS_AVR_FW_DIR "/" name ".elf"

#define BOOT_NS 2000000u /* C runtime start, hubus_slave_init(), the power-up event */

/* Commands and constants of the test firmware. */
#define OP_SET 0x10
#define OP_EVENT 0x11
#define OP_BLIND 0x12
#define BOOT_EVENT 0xB0
#define FW_INFO_TYPE 0x7E
#define FW_BLIND_CLASS 3u
#define FW_SPEED_CLASS 9u
#define FW_SPEED_CLASS_NS 64000u /* edge response time R of class 9 (docs/spec/01-physical-layer.md section 1.5) */

/* Limits for the ATtiny85 at 8 MHz: the response time of the declared speed class, and the stack of the interrupt
 * path that the buffer sizes of the 128 B RAM devices rest on (docs/slave-library.md). */
#define CYCLE_NS (1000000000u / F_CPU_HZ)
#define LIMIT_RESPONSE_CYCLES (FW_SPEED_CLASS_NS / CYCLE_NS)
#define LIMIT_STACK_BYTES 48u

static fx_t fx;
static avr_bus_t bus;

void setUp(void)
{
    fx_init(&fx);
    avr_bus_init(&bus, &fx.sim);
}

void tearDown(void)
{
    fx_check(&fx);
    avr_bus_free(&bus);
}

static avr_slave_t *add(const char *elf)
{
    return avr_bus_add(&bus, elf, MCU, F_CPU_HZ);
}

static void boot(void)
{
    avr_bus_idle(&bus, BOOT_NS);
    fx_startup(&fx);
}

static void command(uint8_t mcid, uint8_t op, const uint8_t *args, uint8_t len)
{
    TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_send_command(&fx.master, 6, mcid, op, args, len));
}

static void read_state(uint8_t mcid, hubus_slave_frame_t *f)
{
    TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_request_state(&fx.master, mcid, f));
    TEST_ASSERT_EQUAL_UINT8(mcid, f->mcid);
    TEST_ASSERT_EQUAL_UINT8(2, f->len);
}

/* Bursts until no event is announced any more; the frames are in fx.log (of the last burst with data). */
static unsigned collect_events(fx_rec_t *out, unsigned max)
{
    unsigned n = 0;
    int rounds;

    for (rounds = 0; rounds < 8; rounds++) {
        uint8_t event = 0;
        hubus_burst_stats_t st;
        unsigned i;

        TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_check_event(&fx.master, &event));
        if (!event && rounds > 0) {
            break;
        }
        TEST_ASSERT_EQUAL(HUBUS_OK, fx_burst(&fx, &st));
        for (i = 0; i < fx.n_log && n < max; i++) {
            out[n++] = fx.log[i];
        }
        avr_bus_idle(&bus, 500000u);
    }
    return n;
}

/* ---- protocol on the device ------------------------------------------------------------------------------------ */

static void test_slave_info_from_flash(void)
{
    hubus_slave_frame_t f;

    add(FW("fw_slave_5"));
    add(FW("fw_command_10"));
    boot();

    TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_request_info(&fx.master, 5, &f));
    TEST_ASSERT_EQUAL_UINT8(HUBUS_S_INFO, f.type);
    TEST_ASSERT_EQUAL_UINT8(5, f.mcid);
    TEST_ASSERT_EQUAL_UINT8(HUBUS_INFO_APP + 3u, f.len);
    TEST_ASSERT_EQUAL_HEX8(HUBUS_CAP_STATUS_CAPTURE | HUBUS_CAP_STATE | HUBUS_CAP_EVENTS,
                           f.payload[HUBUS_INFO_CAPS]);
    TEST_ASSERT_EQUAL_UINT8(31, f.payload[HUBUS_INFO_MAX_CMD]);
    TEST_ASSERT_EQUAL_UINT8(FW_BLIND_CLASS, HUBUS_BLIND_CLASS(f.payload[HUBUS_INFO_TIMING]));
    TEST_ASSERT_EQUAL_UINT8(FW_SPEED_CLASS, f.payload[HUBUS_INFO_TIMING] & HUBUS_SPEED_CLASS_MASK);
    TEST_ASSERT_EQUAL_HEX8(FW_INFO_TYPE, f.payload[HUBUS_INFO_APP]);
    TEST_ASSERT_EQUAL_HEX8(5, f.payload[HUBUS_INFO_APP + 2u]);

    TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_request_info(&fx.master, 10, &f));
    TEST_ASSERT_EQUAL_UINT8(10, f.mcid);
    TEST_ASSERT_EQUAL_HEX8(0, f.payload[HUBUS_INFO_CAPS]);
    TEST_ASSERT_EQUAL_HEX8(10, f.payload[HUBUS_INFO_APP + 2u]);
}

static void test_command_and_state(void)
{
    hubus_slave_frame_t f;
    uint8_t v = 0x5A;

    add(FW("fw_slave_5"));
    add(FW("fw_passive_9"));
    boot();

    command(5, OP_SET, &v, 1);
    v = 0xC3;
    command(9, OP_SET, &v, 1);
    read_state(5, &f);
    TEST_ASSERT_EQUAL_HEX8(0x5A, f.payload[0]);
    read_state(9, &f);
    TEST_ASSERT_EQUAL_HEX8(0xC3, f.payload[0]);

    /* a slave without the event buffer does not answer REQUEST_DATA */
    TEST_ASSERT_EQUAL(HUBUS_ERR_NO_RESPONSE, hubus_master_request_data(&fx.master, 9, &f));
}

static void test_power_up_events_arbitrate_with_host_slaves(void)
{
    fx_rec_t ev[8];
    unsigned n;

    fx_add(&fx, 7); /* host core between the two devices */
    fx_write(&fx, 0, 0x77);
    add(FW("fw_slave_5"));
    add(FW("fw_slave_6"));
    boot();

    n = collect_events(ev, 8);
    TEST_ASSERT_EQUAL_UINT(3, n);
    TEST_ASSERT_EQUAL_UINT8(7, ev[0].mcid); /* descending MCID order */
    TEST_ASSERT_EQUAL_HEX8(0x77, ev[0].first);
    TEST_ASSERT_EQUAL_UINT8(6, ev[1].mcid);
    TEST_ASSERT_EQUAL_HEX8(BOOT_EVENT, ev[1].first);
    TEST_ASSERT_EQUAL_UINT8(5, ev[2].mcid);
    TEST_ASSERT_EQUAL_HEX8(BOOT_EVENT, ev[2].first);
}

static void test_event_written_by_the_main_loop(void)
{
    static const uint8_t data[4] = {0xDE, 0xAD, 0xBE, 0xEF};
    hubus_slave_frame_t f;
    fx_rec_t ev[4];
    unsigned n;

    add(FW("fw_slave_5"));
    add(FW("fw_slave_6"));
    boot();
    (void)collect_events(ev, 4); /* the power-up events */

    command(6, OP_EVENT, data, sizeof data);
    avr_bus_idle(&bus, 200000u); /* the main loop writes, the device signals the event on the idle bus */
    n = collect_events(ev, 4);
    TEST_ASSERT_EQUAL_UINT(1, n);
    TEST_ASSERT_EQUAL_UINT8(6, ev[0].mcid);
    TEST_ASSERT_EQUAL_UINT8(4, ev[0].len);
    TEST_ASSERT_EQUAL_HEX8(0xDE, ev[0].first);
    read_state(6, &f);
    TEST_ASSERT_EQUAL_UINT8(1, f.payload[1]); /* one finished job */
}

static void test_status_capture_of_the_group(void)
{
    fx_rec_t ev[4];
    uint8_t v;
    unsigned n;

    add(FW("fw_slave_5"));
    add(FW("fw_slave_6"));
    boot();
    (void)collect_events(ev, 4);

    v = 0x15;
    command(5, OP_SET, &v, 1);
    v = 0x16;
    command(6, OP_SET, &v, 1);
    TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_status_capture(&fx.master, 0, 0));
    n = collect_events(ev, 4);
    TEST_ASSERT_EQUAL_UINT(2, n);
    TEST_ASSERT_EQUAL_UINT8(6, ev[0].mcid);
    TEST_ASSERT_EQUAL_HEX8(0x16, ev[0].first);
    TEST_ASSERT_EQUAL_UINT8(5, ev[1].mcid);
    TEST_ASSERT_EQUAL_HEX8(0x15, ev[1].first);
}

/* A blind section with interrupts disabled while the master talks to the other device; afterwards the blind device
 * answers again, and nothing it missed was misread. */
static void test_blind_section_with_interrupts_disabled(void)
{
    hubus_slave_frame_t f;
    fx_rec_t ev[4];
    uint8_t n = 8; /* 0.8 ms */
    uint8_t v;
    int i;

    add(FW("fw_slave_5"));
    add(FW("fw_slave_6"));
    boot();
    (void)collect_events(ev, 4);

    command(5, OP_BLIND, &n, 1);
    for (i = 0; i < 6; i++) { /* foreign traffic during the blind time: commands and state reads of slave 6 */
        v = (uint8_t)(0x60 + i);
        command(6, OP_SET, &v, 1);
        read_state(6, &f);
        TEST_ASSERT_EQUAL_HEX8(v, f.payload[0]);
    }
    avr_bus_idle(&bus, HUBUS_BLIND_US(FW_BLIND_CLASS) * 1000u);
    TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_reset(&fx.master)); /* ends the blind time (section 6.9) */

    read_state(5, &f);
    TEST_ASSERT_EQUAL_UINT8(1, f.payload[1]); /* the blind section ran */
    v = 0x55;
    command(5, OP_SET, &v, 1);
    read_state(5, &f);
    TEST_ASSERT_EQUAL_HEX8(0x55, f.payload[0]);
    TEST_ASSERT_EQUAL_UINT(0, collect_events(ev, 4));
}

/* ---- measurements ------------------------------------------------------------------------------------------------ */

static void report(const char *name, const avr_slave_t *d)
{
    uint32_t ns = avr_slave_cycle_ns(d);

    printf("%s (%s at %u MHz): %u ISRs, longest ISR %u cycles (%u ns), longest response %u cycles (%u ns), "
           "stack %u bytes, of which the ISR at most %u\n",
           name, MCU, F_CPU_HZ / 1000000u, d->isr_count, (unsigned)d->isr_max_cycles,
           (unsigned)(d->isr_max_cycles * ns), (unsigned)d->response_max_cycles,
           (unsigned)(d->response_max_cycles * ns), avr_slave_stack_depth(d),
           (unsigned)(d->isr_sp_entry_max - d->isr_sp_min));
}

/* All transaction types against both builds: the response stays within the declared speed class (the longest one is
 * the falling edge after the turnaround slot of an exact request, which starts the answer), the stack within its
 * limit. */
static void test_isr_time_and_stack_within_limits(void)
{
    static const uint8_t big[30] = {0};
    hubus_slave_frame_t f;
    fx_rec_t ev[4];
    avr_slave_t *full;
    avr_slave_t *cmd;
    uint8_t v = 1;

    full = add(FW("fw_slave_5"));
    cmd = add(FW("fw_command_10"));
    boot();
    (void)collect_events(ev, 4);
    TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_request_info(&fx.master, 5, &f));
    TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_request_info(&fx.master, 10, &f));
    command(5, OP_SET, &v, 1);
    command(10, OP_SET, &v, 1);
    command(5, 0x20, big, sizeof big); /* longest command, unknown opcode */
    read_state(5, &f);
    TEST_ASSERT_EQUAL(HUBUS_OK, hubus_master_status_capture(&fx.master, 0, 0));
    (void)collect_events(ev, 4);

    report("fw_slave_5", full);
    report("fw_command_10", cmd);
    TEST_ASSERT_TRUE(full->isr_count > 1000u);
    TEST_ASSERT_LESS_OR_EQUAL_UINT32(LIMIT_RESPONSE_CYCLES, full->response_max_cycles);
    TEST_ASSERT_LESS_OR_EQUAL_UINT(LIMIT_STACK_BYTES, avr_slave_stack_depth(full));
    TEST_ASSERT_LESS_OR_EQUAL_UINT32(LIMIT_RESPONSE_CYCLES, cmd->response_max_cycles);
    TEST_ASSERT_LESS_OR_EQUAL_UINT(LIMIT_STACK_BYTES, avr_slave_stack_depth(cmd));
}

/* ---- timing ------------------------------------------------------------------------------------------------------ */

/* Master minimums: `half` for T_CLK_LOW, T_CLK_HIGH, and T_COND (T_SAMPLE in the middle), `turn` for T_TURNAROUND. */
static void set_timing(uint32_t half, uint32_t turn)
{
    hubus_master_hal_t hal = hubus_sim_master_hal(&fx.sim);

    fx.cfg.t_clk_low_ns = half;
    fx.cfg.t_clk_high_ns = half;
    fx.cfg.t_sample_ns = half / 2u;
    fx.cfg.t_cond_ns = half;
    fx.cfg.t_turnaround_ns = turn;
    hubus_master_init(&fx.master, &hal, &fx.cfg);
    hubus_sim_check_timing(&fx.sim, half, half, half);
}

/* One round of traffic without assertions: NULL if every transaction succeeded and the line rules held, else the
 * step that failed. */
static const char *traffic_failure(void)
{
    hubus_slave_frame_t f;
    hubus_burst_stats_t st;
    uint8_t v = 0xA5;
    uint8_t event = 0;

    if (hubus_master_startup(&fx.master) != HUBUS_OK) {
        return "startup";
    }
    if (hubus_master_check_event(&fx.master, &event) != HUBUS_OK || fx_burst(&fx, &st) != HUBUS_OK ||
        st.served != 2u) {
        return "burst";
    }
    if (hubus_master_send_command(&fx.master, 6, 5, OP_SET, &v, 1) != HUBUS_OK ||
        hubus_master_request_state(&fx.master, 5, &f) != HUBUS_OK || f.len != 2u || f.payload[0] != v) {
        return "command and state";
    }
    if (hubus_master_request_info(&fx.master, 6, &f) != HUBUS_OK || f.mcid != 6u) {
        return "info";
    }
    if (fx.sim.violations) {
        return "DATA changed while CLK was high";
    }
    return fx.sim.timing_violations ? "master timing" : NULL;
}

/* Two fresh devices booted, then one round of traffic with the given minimums. */
static const char *traffic_with(uint32_t half, uint32_t turn)
{
    avr_bus_free(&bus);
    fx_init(&fx);
    avr_bus_init(&bus, &fx.sim);
    add(FW("fw_slave_5"));
    add(FW("fw_slave_6"));
    avr_bus_idle(&bus, BOOT_NS);
    set_timing(half, turn);
    return traffic_failure();
}

/* With every master minimum set to the response time of the declared speed class, the bus works (section 1.5:
 * T_CLK_LOW, T_CLK_HIGH, T_COND, and T_TURNAROUND each at least R). Shorter half periods then report the actual
 * margin, as input for the timing values of section 1.4. (The master never makes T_TURNAROUND shorter than
 * T_CLK_LOW, so the half period is the only value to sweep.) */
static void test_declared_speed_class_holds(void)
{
    static const uint32_t half_ns[] = {56000, 50000, 45000, 40000, 35000, 30000, 25000, 20000, 15000, 10000};
    const char *failure = traffic_with(FW_SPEED_CLASS_NS, FW_SPEED_CLASS_NS);
    uint32_t shortest = FW_SPEED_CLASS_NS;
    unsigned i;

    TEST_ASSERT_NULL_MESSAGE(failure, failure);
    for (i = 0; i < sizeof half_ns / sizeof half_ns[0]; i++) {
        failure = traffic_with(half_ns[i], half_ns[i]);
        if (failure) {
            printf("clock half period %u ns: %s failed\n", (unsigned)half_ns[i], failure);
            break;
        }
        shortest = half_ns[i];
    }
    printf("shortest clock half period without errors: %u ns (%s at %u MHz)\n", (unsigned)shortest, MCU,
           F_CPU_HZ / 1000000u);
    /* the failed run leaves violations behind; only the passing runs count */
    fx.sim.violations = 0;
    fx.sim.timing_violations = 0;
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_slave_info_from_flash);
    RUN_TEST(test_command_and_state);
    RUN_TEST(test_power_up_events_arbitrate_with_host_slaves);
    RUN_TEST(test_event_written_by_the_main_loop);
    RUN_TEST(test_status_capture_of_the_group);
    RUN_TEST(test_blind_section_with_interrupts_disabled);
    RUN_TEST(test_isr_time_and_stack_within_limits);
    RUN_TEST(test_declared_speed_class_holds);
    return UNITY_END();
}
